const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const startDate = '2005-07-12';
    const endDate = '2005-07-19';

    // Get US States geometries
    const states = ee.FeatureCollection('TIGER/2018/States');
    const californiaGeom = states.filter(ee.Filter.eq('NAME', 'California')).geometry();
    const mississippiGeom = states.filter(ee.Filter.eq('NAME', 'Mississippi')).geometry();

    // 2. Data Acquisition
    const modisLST = ee.ImageCollection('MODIS/006/MOD11A1')
        .filterDate(startDate, endDate);

    // Check if collection is empty
    const collectionSize = modisLST.size().getInfo();
    if (collectionSize === 0) {
        console.log('No MODIS images found for the specified date range.');
        console.log('A'); // A is a placeholder for the final answer tag
        console.log('B');
        console.log('C2');
        console.log('C3');
        console.log('D');
        console.log('C1');
        return;
    }
    console.log(`Image collection size: ${collectionSize}`);

    // 3. Processing
    // Function to mask low-quality pixels and convert to Celsius
    const processLST = function(image) {
        const qa = image.select('QC_Day');
        // Bits 0-1: Mandatory QA flags. 00 = LST produced, good quality
        const qualityMask = qa.bitwiseAnd(3).eq(0);
        const lst = image.select('LST_Day_1km')
            .multiply(0.02) // Apply scale factor to get Kelvin
            .subtract(273.15); // Convert Kelvin to Celsius
        return lst.updateMask(qualityMask);
    };

    // Create a single composite image (mean) for the period
    const lstComposite = modisLST.map(processLST).mean();

    // 4. Calculation & Validation
    const scale = 3000; // Use a coarse scale to avoid timeouts

    // Calculate mean LST for California
    const caStats = lstComposite.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: californiaGeom,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const caTemp = caStats['LST_Day_1km_mean'];
    const caPixels = caStats['LST_Day_1km_count'];

    // Calculate mean LST for Mississippi
    const msStats = lstComposite.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: mississippiGeom,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const msTemp = msStats['LST_Day_1km_mean'];
    const msPixels = msStats['LST_Day_1km_count'];

    // 5. Final Answer
    console.log(`California: Mean LST = ${caTemp ? caTemp.toFixed(2) : 'N/A'} C, Valid Pixels = ${caPixels || 0}`);
    console.log(`Mississippi: Mean LST = ${msTemp ? msTemp.toFixed(2) : 'N/A'} C, Valid Pixels = ${msPixels || 0}`);

    if (caPixels === 0 || msPixels === 0) {
        console.log('No valid pixels found for one or both states after cloud masking.');
        console.log('C2');
        return;
    }

    if (caTemp === null || msTemp === null || isNaN(caTemp) || isNaN(msTemp)) {
        console.log('Calculation failed, resulting in null or NaN values.');
        console.log('C3');
        return;
    }

    if (caTemp > msTemp) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
